mapper.select:
SELECT p.* FROM arc_profile p WHERE 1 = 1
AND p.section_code = #{sectionCode}
AND p.status = #{status}
AND p.academic_year = #{academicYear}
AND EXISTS ( SELECT 1 FROM arc_profile bp JOIN arc_profile_item ci ON ci.profile_id = bp.id WHERE bp.student_id = p.student_id AND bp.academic_year = p.academic_year AND bp.section_code = 'BASIC' AND ci.field_code = 'basic.classId' AND ci.value_text = #{classId} )
AND EXISTS ( SELECT 1 FROM arc_profile bp JOIN arc_profile_item ci ON ci.profile_id = bp.id JOIN org_class c ON c.class_code = ci.value_text WHERE bp.student_id = p.student_id AND bp.academic_year = p.academic_year AND bp.section_code = 'BASIC' AND ci.field_code = 'basic.classId' AND c.counselor_user_id = #{counselorId} )
ORDER BY p.submitted_at DESC, p.id DESC

SELECT bp.student_id AS studentId, ci.field_code AS fieldCode, ci.value_text AS valueText FROM arc_profile bp JOIN arc_profile_item ci ON ci.profile_id = bp.id WHERE bp.section_code = 'BASIC' AND bp.academic_year = #{academicYear} AND bp.student_id IN
#{studentId}
AND ci.field_code IN
#{fieldCode}
